import { useState } from 'react';
import {
  JxBadge,
  JxDivider,
  JxSelect,
  JxSlider,
  JxSwitch,
  JxToggle,
} from '@jinx-ui/react';

export type AppearanceSettings = {
  theme: 'light' | 'dark' | 'system';
  scale: number;
  dense: boolean;
  font: string;
};

const THEMES: { value: AppearanceSettings['theme']; label: string }[] = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const FONTS = [
  { value: 'sans', label: 'Без засечек', meta: 'по умолчанию' },
  { value: 'display', label: 'Акцидентный' },
  { value: 'mono', label: 'Моноширинный' },
];

export default function AppearanceSettingsScreen({
  defaultSettings,
  onChange,
}: {
  defaultSettings?: Partial<AppearanceSettings>;
  onChange?: (settings: AppearanceSettings) => void;
}) {
  const [settings, setSettings] = useState<AppearanceSettings>({
    theme: 'system',
    scale: 100,
    dense: false,
    font: 'sans',
    ...defaultSettings,
  });

  const update = (patch: Partial<AppearanceSettings>) => {
    setSettings((prev) => {
      const next = { ...prev, ...patch };
      onChange?.(next);
      return next;
    });
  };

  const themeLabel =
    THEMES.find((item) => item.value === settings.theme)?.label ?? 'Системная';

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '1.5rem',
        maxWidth: '32rem',
        padding: '1.5rem',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        color: 'var(--jx-text)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <header
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '1rem',
          flexWrap: 'wrap',
        }}
      >
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            fontSize: '1.125rem',
            color: 'var(--jx-text)',
          }}
        >
          Внешний вид
        </h2>
        <JxBadge tone="accent" dot>
          {themeLabel}
        </JxBadge>
      </header>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
        <span style={{ fontSize: '0.875rem', color: 'var(--jx-text-2)' }}>
          Тема оформления
        </span>
        <JxToggle
          items={THEMES}
          value={settings.theme}
          onValueChange={(value) =>
            update({ theme: value as AppearanceSettings['theme'] })
          }
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={10}
        unit="%"
        showOutput
        value={settings.scale}
        onValueChange={(value) => update({ scale: value })}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={settings.dense}
        onChange={(event) => update({ dense: event.target.checked })}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт интерфейса"
        placeholder="Выберите шрифт"
        options={FONTS}
        value={settings.font}
        onValueChange={(value) => update({ font: value })}
      />
    </section>
  );
}

